javascript:(function () {
    var uid = new x_nasm_hr.ACN_ValidateUtils().getUser();

    function ymd(gdt) {
        return gdt.getDate().getValue();
    }

    var now = new GlideDateTime();

    // Limite mais recente: hoje - 4 meses
    var gMaxRecent = new GlideDateTime(now.getValue());
    gMaxRecent.addMonthsUTC(-4);
    var maxRecentDob = ymd(gMaxRecent); // criança mais nova possível

    // Limite mais antigo: hoje - 2 anos, 11 meses, 29 dias
    var gMaxOld = new GlideDateTime(now.getValue());
    gMaxOld.addYearsUTC(-2);
    gMaxOld.addMonthsUTC(-11);
    gMaxOld.addDaysUTC(-29);
    var maxOldDob = ymd(gMaxOld); // criança mais velha possível

    var relIds = [
        '4d8615921bbeb810a530426fe54bcb35',
        '098615921bbeb810a530426fe54bcb59',
        'cd8615921bbeb810a530426fe54bcb31',
        '858615921bbeb810a530426fe54bcb5d',
        'e808b1711bd68510a530426fe54bcbc4',
        'd9eb31751bd68510a530426fe54bcb79',
        '34c7f9711bd68510a530426fe54bcb27'
    ];

    return 'employee=' + uid +
           '^relationshipIN' + relIds.join(',') +
           '^status!=delete' +
           '^date_of_birth<=' + maxRecentDob +   // não pode ser mais novo que 4 meses
           '^date_of_birth>=' + maxOldDob;      // não pode ser mais velho que 2a 11m 29d
})()
